observations.before:
[package]
workspace = "../../../../../../.."
name = "semio-framework-os-flow"
version = "0.1.0"
edition = "2021"
rust-version.workspace = true
description = "OS flow family — document/host/vcs and supplied geometry ports; operators (light/draw/brep/bim) are packaged extensions"

[package.metadata.semio]
role = "product"
id = "os-flow"

[package.metadata.wasm-pack.profile.release]
wasm-opt = ["-O", "--enable-bulk-memory", "--enable-nontrapping-float-to-int"]

[package.metadata.wasm-pack.profile.custom]
wasm-opt = ["-O", "--enable-bulk-memory", "--enable-nontrapping-float-to-int"]

[lints]
workspace = true

[lib]
name = "semio_framework_os_flow"
crate-type = ["cdylib", "rlib"]
path = "🦀️.rs"

[dependencies]
semio-framework-dsl-record = { path = "../../../../../../🔨️modules/🗣️dsl/🧬️schema/📦️packages/🦀️rust" }
semio-framework-pack-json = { path = "../../../../../../🔨️modules/🎒️pack/🔤️json/📦️packages/🦀️rust" }
semio-framework-ui-locale = { path = "../../../../../../🔨️modules/🖱️ui/🌐️locale/📦️packages/🦀️rust" }
semio-framework-value = { path = "../../../../../../🔨️modules/🌱️value/📦️packages/🦀️rust" }
semio-framework-artifact-infinite-dag = { workspace = true }
semio-framework-artifact-flow-flow = { workspace = true }
semio-framework-artifact-playbook-playbook = { workspace = true }
semio-framework-os-kernel = { path = "../../../../📦️packages/🦀️rust", package = "semio-framework-os-kernel" }
semio-framework-value-derive = { path = "../../../../../../🔨️modules/🌱️value/✨️derive/📦️packages/🦀️rust", package = "semio-framework-value-derive" }
semio-framework-os-infinite = { path = "../../../♾️infinite/📦️packages/🦀️rust", package = "semio-framework-os-infinite" }
semio-framework = { path = "../../../../../../📦️packages/🦀️rust", package = "semio-framework" }
semio-framework-job = { workspace = true }
semio-framework-plugin = { path = "../../../🔌️plugin/📦️packages/🦀️rust" }
# 🤝 `browser::future_to_promise` — the owned Promise ABI `flowAttachSurfaceCanvas` resolves through
# (🕸️wasm/🦀️.rs, `surface_canvas`). Unconditional because the module itself is gated.
semio-framework-async = { workspace = true }
semio-framework-replication = { workspace = true }
neural_engine = { path = "../../../🧠️neural/⚙️engine/📦️packages/🦀️rust", package = "semio-framework-os-kernel-neural-engine" }
math = { path = "../../../../../../🔨️modules/🧮️math/📦️packages/🦀️rust", package = "semio-framework-math" }
graph = { path = "../../../../../../🔨️modules/🕸️graph/📦️packages/🦀️rust", package = "semio-framework-graph" }
ui_styling = { path = "../../../../../../🔨️modules/🖱️ui/🎨️styling/📦️packages/🦀️rust", package = "semio-framework-ui-styling" }
ui_wgpu = { path = "../../../../../../🔨️modules/🖱️ui/📦️packages/🦀️rust", package = "semio-framework-ui", features = ["wgpu"] }
semio-framework-3d = { path = "../../../../../../🔨️modules/🧊️3d/📦️packages/🦀️rust" }
semio-framework-2d = { path = "../../../../../../🔨️modules/◻️2d/📦️packages/🦀️rust", features = ["serde"] }
base64 = "0.22"
serde = { version = "1", features = ["derive"] }
serde_json = "1"

[dev-dependencies]
semio-framework-artifact-flow-flow = { workspace = true, features = ["protocol-laws"] }
# 🧪️ `ordered-set-serde`: this crate's own `Widget::OutputPreview`/`FlowPreviewGui`
# (🗿️artifact/🦀️.rs) carry `#[cfg_attr(test, derive(Serialize, Deserialize))]` over an
# `OrderedSet` field. `[dependencies]` above pulls plain `semio-framework-replication` (no extra
# features, so `OrderedSet: Serialize`/`Deserialize` isn't compiled for a normal build); listing it
# again here with the feature makes Cargo's dev-dependency feature unification enable it only for
# `--tests`/`cargo test` builds of THIS crate — see `protocol`'s
# `🌱️value/🗂️ordered/🧺️set/🦀️.rs` `ArrayWire` docstring for why plain `#[cfg(test)]` there,
# alone, is not enough for a cross-crate consumer's own test-gated derive.
semio-framework-replication = { workspace = true, features = ["ordered-set-serde"] }
semio-framework-async-macros = { path = "../../../../../../🔨️modules/⏳️async/✨️macros/📦️packages/🦀️rust" }
# 🛡️ Test-only: the fixed per-surface admission constant and `SurfaceKind` the node-graph surface bound
# law (`a_node_graph_surface_stays_under_the_fixed_admission_with_five_hundred_operators`) measures
# against. Nothing in this crate's program logic names the contract crate — the catalogue rides an
# app-scoped section, never a surface payload (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
ui_contract = { path = "../../../../../../🔨️modules/🖱️ui/🧬️contract/📦️packages/🦀️rust", package = "semio-framework-ui-contract" }

# ⚠️ RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS (26/09/01): `ui_wgpu`'s `wgpu-engine`
# feature (the real `wgpu` crate and its `wasm-bindgen-futures`/`js-sys`/`wasm-bindgen` chain) is
# narrowed away from `wasm32-wasip2` here — nothing this crate's own program logic needs
# (`ui_wgpu::wgpu::{DrawList, ...}` and friends) requires it any more, see
# `🖱️ui/🎯️targets/🧊️wgpu/🦀️.rs`'s top docstring for the wgpu-tier split this depends on.
[target.'cfg(not(all(target_arch = "wasm32", target_env = "p2")))'.dependencies]
ui_wgpu = { path = "../../../../../../🔨️modules/🖱️ui/📦️packages/🦀️rust", package = "semio-framework-ui", features = ["wgpu-engine"] }
# 🌉️ `ui_webgpu` backs only `wasm_session`'s browser wasm-pack SDK bridge (`🦀️.rs`'s own
# gate docstring) — its `ui_render` dependency drags `taffy`/`parley`/`swash`/`fontique` (text
# shaping/layout) unconditionally, none of which a WASI guest needs. Narrowed here rather than
# deleted: native keeps it for this crate's own `#[cfg(test)]` suite over the bridge protocol.
ui_webgpu = { path = "../../../../../../🔨️modules/🖱️ui/🖌️render/🎯️targets/🧊️webgpu/📦️packages/🦀️rust", package = "semio-framework-ui-backend-webgpu" }

# 🌉️ Browser byte-ABI and canvas bindings require a JavaScript engine and are excluded from WASI.
[target.'cfg(all(target_arch = "wasm32", not(target_env = "p2")))'.dependencies]
getrandom = { version = "0.3.4", features = ["wasm_js"] }
wasm-bindgen = "0.2.106"
# 🖼️ `surface_canvas` (🕸️wasm/🦀️.rs) binds the node-graph canvas to the shared
# `CanvasGpuSession` out of band from the byte ABI, which cannot carry an element handle.
js-sys = "0.3.83"
web-sys = { version = "0.3.98", features = ["HtmlCanvasElement"] }

# 🎒️ Preview mesh wire laws (pack record body + chunking + LOD cache) — ticket
# 26/09/09/PROCEDURAL-3D-END-TO-END. Declared as its own `[[test]]` so the cross-language wire
# contract stays runnable from this crate's PUBLIC surface alone.
[[test]]
name = "flow_mesh_pack_wire"
path = "../../🧪️tests/🎒️mesh-pack-wire/🦀️.rs"

